export type Plan = "free" | "pro";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
  plan: Plan;
  /** Set once the user has started a Stripe Checkout session. */
  stripeCustomerId?: string;
  /** Set once the user has an active (or previously active) subscription. */
  stripeSubscriptionId?: string;
};

const users: User[] = [
  {
    id: "1",
    email: "ada@example.com",
    name: "Ada",
    createdAt: "2026-01-04",
    plan: "free",
  },
  {
    id: "2",
    email: "grace@example.com",
    name: "Grace",
    createdAt: "2026-02-11",
    plan: "free",
  },
];

export async function listUsers(): Promise<User[]> {
  return users;
}

export async function getUser(id: string): Promise<User | undefined> {
  return users.find((u) => u.id === id);
}

// TODO: there is no real session handling yet — the dashboard just picks the first user.
export async function getCurrentUser(): Promise<User | undefined> {
  return users[0];
}

export async function getUserByStripeCustomerId(
  customerId: string,
): Promise<User | undefined> {
  return users.find((u) => u.stripeCustomerId === customerId);
}

export async function setStripeCustomerId(
  userId: string,
  customerId: string,
): Promise<void> {
  const user = users.find((u) => u.id === userId);
  if (user) user.stripeCustomerId = customerId;
}

export async function setPlan(
  userId: string,
  plan: Plan,
  subscriptionId?: string,
): Promise<User | undefined> {
  const user = users.find((u) => u.id === userId);
  if (!user) return undefined;
  user.plan = plan;
  if (subscriptionId !== undefined) user.stripeSubscriptionId = subscriptionId;
  return user;
}

export async function upgradeToPro(
  userId: string,
  subscriptionId?: string,
): Promise<User | undefined> {
  return setPlan(userId, "pro", subscriptionId);
}

export async function downgradeToFree(userId: string): Promise<User | undefined> {
  return setPlan(userId, "free");
}

