import { NextRequest, NextResponse } from "next/server";
import Stripe from "stripe";
import { stripe, STRIPE_WEBHOOK_SECRET } from "@/lib/stripe";
import {
  downgradeToFree,
  getUserByStripeCustomerId,
  setStripeCustomerId,
  upgradeToPro,
} from "@/lib/users";

// Stripe sends events here for every payment lifecycle change. This is the
// only place a user's plan actually flips to "pro" — the checkout route
// just starts the payment, it never grants access itself.
export async function POST(request: NextRequest) {
  const body = await request.text();
  const signature = request.headers.get("stripe-signature");

  if (!signature) {
    return NextResponse.json({ error: "Missing stripe-signature header" }, { status: 400 });
  }

  let event: Stripe.Event;
  try {
    event = stripe.webhooks.constructEvent(body, signature, STRIPE_WEBHOOK_SECRET);
  } catch (err) {
    const message = err instanceof Error ? err.message : "Unknown error";
    return NextResponse.json({ error: `Webhook signature verification failed: ${message}` }, { status: 400 });
  }

  switch (event.type) {
    case "checkout.session.completed": {
      const session = event.data.object as Stripe.Checkout.Session;
      const userId = session.client_reference_id;
      const customerId =
        typeof session.customer === "string" ? session.customer : session.customer?.id;
      const subscriptionId =
        typeof session.subscription === "string"
          ? session.subscription
          : session.subscription?.id;

      if (userId && customerId) {
        await setStripeCustomerId(userId, customerId);
        // Payment succeeded — this is the moment the user actually becomes Pro.
        await upgradeToPro(userId, subscriptionId);
      }
      break;
    }

    // Keeps the plan in sync with the subscription's real status — handles
    // renewals, cancellations, and failed-payment downgrades automatically.
    case "customer.subscription.updated":
    case "customer.subscription.deleted": {
      const subscription = event.data.object as Stripe.Subscription;
      const customerId =
        typeof subscription.customer === "string"
          ? subscription.customer
          : subscription.customer?.id;
      if (!customerId) break;

      const user = await getUserByStripeCustomerId(customerId);
      if (!user) break;

      const isActive = subscription.status === "active" || subscription.status === "trialing";
      if (isActive) {
        await upgradeToPro(user.id, subscription.id);
      } else {
        await downgradeToFree(user.id);
      }
      break;
    }

    default:
      // Ignore anything we don't act on.
      break;
  }

  return NextResponse.json({ received: true });
}

