import { getCurrentUser, listUsers } from "@/lib/users";

export default async function DashboardPage({
  searchParams,
}: {
  searchParams: Promise<{ checkout?: string }>;
}) {
  const me = await getCurrentUser();
  const all = await listUsers();
  const { checkout } = await searchParams;

  return (
    <main className="mx-auto max-w-2xl p-8">
      <h1 className="text-2xl font-semibold">Dashboard</h1>
      <p className="mt-2 text-sm opacity-70">
        Signed in as {me?.name ?? "nobody"} ({me?.email ?? "—"})
      </p>

      {checkout === "success" && (
        <p className="mt-4 rounded border border-green-600/30 bg-green-600/10 px-3 py-2 text-sm text-green-700 dark:text-green-400">
          Payment received — welcome to Pro! It may take a few seconds to
          appear below.
        </p>
      )}
      {checkout === "cancelled" && (
        <p className="mt-4 rounded border border-amber-600/30 bg-amber-600/10 px-3 py-2 text-sm text-amber-700 dark:text-amber-400">
          Checkout cancelled — you have not been charged.
        </p>
      )}
      {checkout === "error" && (
        <p className="mt-4 rounded border border-red-600/30 bg-red-600/10 px-3 py-2 text-sm text-red-700 dark:text-red-400">
          Something went wrong starting checkout. Please try again.
        </p>
      )}

      <section className="mt-8 rounded-lg border border-black/10 p-4 dark:border-white/10">
        <div className="flex items-center justify-between">
          <div>
            <h2 className="text-lg font-medium">Plan</h2>
            <p className="mt-1 text-sm opacity-70">
              You&apos;re currently on the{" "}
              <span className="font-semibold uppercase">{me?.plan ?? "free"}</span>{" "}
              plan.
            </p>
          </div>

          {me?.plan === "pro" ? (
            <form action="/api/portal" method="POST">
              <button
                type="submit"
                className="rounded-full border border-black/10 px-4 py-2 text-sm font-medium hover:bg-black/[.04] dark:border-white/10 dark:hover:bg-white/[.06]"
              >
                Manage billing
              </button>
            </form>
          ) : (
            <form action="/api/checkout" method="POST">
              <button
                type="submit"
                className="rounded-full bg-foreground px-4 py-2 text-sm font-medium text-background hover:bg-[#383838] dark:hover:bg-[#ccc]"
              >
                Upgrade to Pro — $12/mo
              </button>
            </form>
          )}
        </div>
      </section>

      <h2 className="mt-8 text-lg font-medium">Team</h2>
      <ul className="mt-2 space-y-1">
        {all.map((u) => (
          <li key={u.id} className="text-sm">
            {u.name} — {u.email} — joined {u.createdAt} —{" "}
            <span className="opacity-70">{u.plan}</span>
          </li>
        ))}
      </ul>
    </main>
  );
}

